MagickBooleanType WriteMAPImage(const ImageInfo *image_info, Image *image) {
  MagickBooleanType status = MagickTrue;
  FILE *file = (FILE *) NULL;
  size_t colormap_length = 0;
  register PixelIndex *p;
  PixelIndex *indexes = (PixelIndex *) NULL;
  register unsigned char *q;
  unsigned char *colormap = (unsigned char *) NULL;
  size_t length;

  if ((image_info == (ImageInfo *) NULL) || (image == (Image *) NULL))
    return (MagickFalse);

  if ((image->storage_class != PseudoClass) || (image->colors > 256)) {
    (void) ThrowMagickException(&image->exception, GetMagickModule(),
      ImageError, "ImageNotPseudoClass","%s is not a PseudoClass image",
      image->filename);
    return (MagickFalse);
  }

  if (image->colors == 0) {
    (void) ThrowMagickException(&image->exception, GetMagickModule(),
      ImageError, "ImageHasNoColors","%s has no colors",
      image->filename);
    return (MagickFalse);
  }

  if ((file = fopen(image->filename, "wb")) == (FILE *) NULL) {
    (void) ThrowMagickException(&image->exception, GetMagickModule(),
      FileError, "UnableToCreateFile","%s", image->filename);
    return (MagickFalse);
  }

  if (image->colors > 256) {
    colormap_length = image->colors * 3;
  } else {
    colormap_length = 256 * 3;
  }

  colormap = (unsigned char *) AcquireMemory(colormap_length);
  if (colormap == (unsigned char *) NULL) {
    (void) fclose(file);
    (void) ThrowMagickException(&image->exception, GetMagickModule(),
      ResourceLimitError, "UnableToAllocateMemory","%s",
      "colormap");
    return (MagickFalse);
  }

  p = GetPixelIndexes(image);
  if (p == (PixelIndex *) NULL) {
    (void) fclose(file);
    RelinquishMemory(colormap);
    (void) ThrowMagickException(&image->exception, GetMagickModule(),
      ResourceLimitError, "UnableToAllocateMemory","%s",
      "pixel indexes");
    return (MagickFalse);
  }

  for (length = 0; length < image->colors; length++) {
    colormap[length * 3] = (unsigned char) ScaleQuantumToChar(image->colormap[length].red);
    colormap[length * 3 + 1] = (unsigned char) ScaleQuantumToChar(image->colormap[length].green);
    colormap[length * 3 + 2] = (unsigned char) ScaleQuantumToChar(image->colormap[length].blue);
  }

  if (fwrite(colormap, 1, colormap_length, file) != colormap_length) {
    (void) fclose(file);
    RelinquishMemory(colormap);
    (void) ThrowMagickException(&image->exception, GetMagickModule(),
      FileError, "UnableToWriteFile","%s", image->filename);
    return (MagickFalse);
  }

  indexes = GetPixelIndexes(image);
  if (indexes == (PixelIndex *) NULL) {
    (void) fclose(file);
    RelinquishMemory(colormap);
    (void) ThrowMagickException(&image->exception, GetMagickModule(),
      ResourceLimitError, "UnableToAllocateMemory","%s",
      "pixel indexes");
    return (MagickFalse);
  }

  for (length = 0; length < image->columns * image->rows; length++) {
    if (fwrite(indexes + length, 1, 1, file) != 1) {
      (void) fclose(file);
      RelinquishMemory(colormap);
      (void) ThrowMagickException(&image->exception, GetMagickModule(),
        FileError, "UnableToWriteFile","%s", image->filename);
      return (MagickFalse);
    }
  }

  (void) fclose(file);
  RelinquishMemory(colormap);
  return (status);
}
